mermaid:
%%{init: {'flowchart': {'curve': 'linear'}}}%%
graph TD;
	__start__([<p>__start__</p>]):::first
	agent(agent)
	tools(tools)
	confirm(confirm)
	apply(apply)
	declined(declined)
	__end__([<p>__end__</p>]):::last
	__start__ --> agent;
	apply --> agent;
	declined --> agent;
	agent -.-> tools;
	agent -.-> __end__;
	tools -.-> confirm;
	tools -.-> agent;
	confirm -.-> apply;
	confirm -.-> declined;
	classDef default fill:#f2f0ff,line-height:1.2;
	classDef first fill-opacity:0;
	classDef last fill:#bfb6fc;
